mapper.select:
SELECT d.DISPOSAL_ID, d.DISPOSAL_NO, d.DISPOSAL_TYPE, d.ASSET_ID, d.ORIGINAL_VALUE, d.NET_VALUE, d.DISPOSAL_INCOME, d.DISPOSAL_PROFIT_LOSS, d.DISPOSAL_DATE, d.REASON, d.STATUS, d.REMARK, d.TENANT_ID, d.CREATE_BY, d.CREATE_TIME, d.UPDATE_BY, d.UPDATE_TIME, d.IS_DELETED, a.ASSET_CODE AS assetCode, a.ASSET_NAME AS assetName FROM TBL_FIXED_ASSET_DISPOSAL d LEFT JOIN TBL_FIXED_ASSET_CARD a ON d.ASSET_ID = a.ASSET_ID AND a.IS_DELETED = 0 WHERE d.IS_DELETED = 0
AND d.TENANT_ID = #{tenantId}
AND d.DISPOSAL_NO LIKE '%' || #{disposalNo} || '%'
AND a.ASSET_CODE LIKE '%' || #{assetCode} || '%'
AND d.DISPOSAL_TYPE = #{disposalType}
AND d.STATUS = #{status}
ORDER BY d.DISPOSAL_DATE DESC, d.CREATE_TIME DESC

SELECT COUNT(*) AS totalCount, NVL(SUM(ORIGINAL_VALUE), 0) AS totalOriginalValue, NVL(SUM(NET_VALUE), 0) AS totalNetValue, NVL(SUM(DISPOSAL_INCOME), 0) AS totalDisposalIncome, NVL(SUM(DISPOSAL_PROFIT_LOSS), 0) AS totalDisposalProfitLoss FROM TBL_FIXED_ASSET_DISPOSAL WHERE IS_DELETED = 0
AND TENANT_ID = #{tenantId}
AND DISPOSAL_DATE >= #{disposalDateStart}
AND DISPOSAL_DATE <= #{disposalDateEnd}
